CREATE TABLE admins(id INTEGER PRIMARY KEY CHECK(id=1), username TEXT UNIQUE NOT NULL,password_hash TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE admin_sessions(id TEXT PRIMARY KEY,token_hash TEXT UNIQUE NOT NULL,created_at TEXT NOT NULL,expires_at TEXT NOT NULL,last_seen_at TEXT);
CREATE TABLE servers(id TEXT PRIMARY KEY,display_name TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',visibility TEXT NOT NULL CHECK(visibility IN ('public','private')),created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE releases(id INTEGER PRIMARY KEY AUTOINCREMENT,server_id TEXT NOT NULL REFERENCES servers(id),name TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('draft','published')),minecraft_version TEXT NOT NULL,loader_constraint TEXT NOT NULL,java_constraint TEXT NOT NULL,min_client_version TEXT NOT NULL DEFAULT '0.1.0',created_at TEXT NOT NULL,published_at TEXT,payload BLOB);
CREATE TABLE channels(server_id TEXT NOT NULL REFERENCES servers(id),name TEXT NOT NULL,active_release_id INTEGER REFERENCES releases(id),created_at TEXT NOT NULL,PRIMARY KEY(server_id,name));
CREATE TABLE artifacts(sha256 TEXT PRIMARY KEY,filename TEXT NOT NULL,size INTEGER NOT NULL,storage_backend TEXT NOT NULL,storage_key TEXT NOT NULL,mod_id TEXT NOT NULL,mod_name TEXT NOT NULL,mod_version TEXT NOT NULL,mod_environment TEXT NOT NULL,fabric_metadata TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE release_mods(release_id INTEGER NOT NULL REFERENCES releases(id),mod_id TEXT NOT NULL,display_name TEXT NOT NULL DEFAULT '',requirement TEXT NOT NULL CHECK(requirement IN ('required','optional','forbidden')),artifact_sha256 TEXT REFERENCES artifacts(sha256),version_constraint TEXT NOT NULL DEFAULT '*',sort_order INTEGER NOT NULL DEFAULT 0,default_selected INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(release_id,mod_id),CHECK((requirement='forbidden' AND artifact_sha256 IS NULL) OR (requirement!='forbidden' AND artifact_sha256 IS NOT NULL)));
CREATE TABLE enrollment_codes(id TEXT PRIMARY KEY,server_id TEXT NOT NULL REFERENCES servers(id),code_hash TEXT UNIQUE NOT NULL,expires_at TEXT NOT NULL,max_uses INTEGER NOT NULL CHECK(max_uses>0),use_count INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL,revoked_at TEXT);
CREATE TABLE client_devices(id TEXT PRIMARY KEY,server_id TEXT NOT NULL REFERENCES servers(id),name TEXT NOT NULL,token_hash TEXT UNIQUE NOT NULL,created_at TEXT NOT NULL,last_seen_at TEXT,revoked_at TEXT);
CREATE TABLE audit_logs(id INTEGER PRIMARY KEY AUTOINCREMENT,actor_type TEXT NOT NULL,actor_id TEXT,action TEXT NOT NULL,object_type TEXT,object_id TEXT,details_json TEXT,created_at TEXT NOT NULL);
CREATE TRIGGER immutable_release_update BEFORE UPDATE ON releases WHEN OLD.status='published' BEGIN SELECT RAISE(ABORT,'published release immutable'); END;
CREATE TRIGGER immutable_release_delete BEFORE DELETE ON releases WHEN OLD.status='published' BEGIN SELECT RAISE(ABORT,'published release immutable'); END;
CREATE TRIGGER immutable_mod_insert BEFORE INSERT ON release_mods WHEN (SELECT status FROM releases WHERE id=NEW.release_id)='published' BEGIN SELECT RAISE(ABORT,'published release immutable'); END;
CREATE TRIGGER immutable_mod_update BEFORE UPDATE ON release_mods WHEN (SELECT status FROM releases WHERE id=OLD.release_id)='published' OR (SELECT status FROM releases WHERE id=NEW.release_id)='published' BEGIN SELECT RAISE(ABORT,'published release immutable'); END;
CREATE TRIGGER immutable_mod_delete BEFORE DELETE ON release_mods WHEN (SELECT status FROM releases WHERE id=OLD.release_id)='published' BEGIN SELECT RAISE(ABORT,'published release immutable'); END;
CREATE INDEX artifact_references ON release_mods(artifact_sha256);
